    id: "re-2021-hl-j-b", topicId: "re-j", conceptId: "similarities-differences-approach-taken-religion-science",
    section: "J", questionRef: "2021 HL Section J Q(b)",
    questionText: "Examine the similarities and differences in the approach taken by religion and science to one of the following debates: • THE DEBATE ABOUT THE ORIGINS OF THE UNIVERSE • THE GENETICS DEBATE",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 80,
    rows: [
    { id: "r-1", kind: "point", verbatim: "The Debate about Origins – both theologians and scientists are driven by the need to understand who we are; the insights of religion address concerns about why the universe exists; the place of people within creation e.g. creationism; ecology of Teillard de Chardin etc; the insights of science address concerns about how the universe came to be and what may happen to the universe in the future e.g. Big Bang etc.", marks: null, contextNote: "An excellent answer will show an understanding of the insights of science and religion in current debates by looking closely at similarities and differences in the approach taken by religion and science to one of the debates listed in the question e.g." },
    { id: "r-2", kind: "point", verbatim: "The Genetics Debate – the insights of science give facts about the embryonic stages of foetal development; both science and religion share concerns about medical ethics; advances in science in recent times raise questions about human stewardship of creation, e.g. artificially created life, cloning, genetically modified life etc.", marks: null },
    ],
